{
  "template": "trigger"
}

namespace heat;
table Settings { seed:ulong; cells:ulong; alpha:double; final_time:double; noise:double; }
table Outputs { settings:Settings (required); }
root_type Outputs;

{
  "template": "input",
  "params": [
    {
      "name": "seed",
      "type": "uint64",
      "data": 3
    },
    {
      "name": "cells",
      "type": "uint64",
      "data": 100
    },
    {
      "name": "alpha",
      "type": "double",
      "data": 1.0
    },
    {
      "name": "final_time",
      "type": "double",
      "data": 0.002
    },
    {
      "name": "noise",
      "type": "double",
      "data": 0.2
    }
  ]
}

namespace heat;
table Measurement { seed:ulong; alpha:double; final_time:double; noise:double; x:[double]; truth:[double]; measured:[double]; }
table Outputs { measurement:Measurement (required); }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "settings"
    }
  ]
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "spectrum",
        "naive",
        "tikhonov",
        "reconstruct",
        "horizon",
        "check"
      ]
    }
  ]
}

namespace heat;
table Outputs { }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "measurement"
    }
  ],
  "params": [
    {
      "name": "time_factors",
      "type": "double[]",
      "data": [
        0.25,
        1,
        4
      ]
    }
  ]
}

namespace heat;
table Outputs { }
